package com.gameaggregator.buildservice.api;import com.gameaggregator.platform.core.common.web.ApiResponse;import com.gameaggregator.buildservice.application.BuildService;import com.gameaggregator.buildservice.domain.*;import jakarta.validation.Valid;import java.util.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/builds") public class BuildController{final BuildService s;public BuildController(BuildService s){this.s=s;}@PostMapping ApiResponse<GameBuild> create(@Valid @RequestBody BuildDtos.Create r){return ApiResponse.success(s.create(r));}@GetMapping ApiResponse<List<GameBuild>> list(@RequestParam(required=false)UUID versionId){return ApiResponse.success(s.list(versionId));}@GetMapping("/{id}")ApiResponse<GameBuild> get(@PathVariable UUID id){return ApiResponse.success(s.get(id));}@PostMapping("/{id}/artifact/presigned-upload")ApiResponse<BuildDtos.UploadUrl> presign(@PathVariable UUID id,@Valid @RequestBody BuildDtos.Presign r){return ApiResponse.success(s.presign(id,r));}@PostMapping("/{id}/artifact/complete")ApiResponse<GameBuild> complete(@PathVariable UUID id,@Valid @RequestBody BuildDtos.Complete r){return ApiResponse.success(s.complete(id,r));}@PatchMapping("/{id}/status")ApiResponse<GameBuild> status(@PathVariable UUID id,@Valid @RequestBody BuildDtos.Status r){return ApiResponse.success(s.status(id,r));}@PostMapping("/{id}/logs")ApiResponse<BuildLog> log(@PathVariable UUID id,@Valid @RequestBody BuildDtos.Log r){return ApiResponse.success(s.log(id,r));}@GetMapping("/{id}/logs")ApiResponse<List<BuildLog>> logs(@PathVariable UUID id){return ApiResponse.success(s.logs(id));}}